using Txt = EduVerse.Core.Catalog.Text;

namespace EduVerse.Core.Tutor;

/// <summary>A curated link between two interview figures: a real, specific fact connecting them (a meeting, a shared
/// fate, an intellectual debt), not just "both were scientists". Bonus content for the figure album, unlocked once
/// the student has completed both figures (see <see cref="Interviews.Connections"/> and <c>FigureDiscoveryStore</c>).</summary>
public sealed record FigureConnection(string FigureA, string FigureB, Txt Insight);

public static partial class Interviews
{
    private static FigureConnection Conn(string a, string b, string insight) => new(a, b, Txt.Of(insight));

    private static readonly IReadOnlyList<FigureConnection> ConnectionList = [
        Conn("galileo", "newton",
            "Newton was born the same year Galileo died, 1642, and built his laws of motion directly on Galileo's studies of falling bodies and inertia — which is why Newton said he had seen further by \"standing on the shoulders of giants\".|Newton nació el mismo año en que murió Galileo, 1642, y construyó sus leyes del movimiento directamente sobre los estudios de Galileo sobre la caída de los cuerpos y la inercia; por eso Newton dijo que había visto más lejos \"a hombros de gigantes\".|Newton est né la même année que la mort de Galilée, en 1642, et a bâti ses lois du mouvement directement sur les études de Galilée sur la chute des corps et l'inertie ; c'est pourquoi Newton disait avoir vu plus loin « juché sur des épaules de géants ».|Newton va néixer el mateix any que va morir Galileu, el 1642, i va construir les seves lleis del moviment directament sobre els estudis de Galileu sobre la caiguda dels cossos i la inèrcia; per això Newton va dir que havia vist més lluny \"a espatlles de gegants\"."),
        Conn("darwin", "newton",
            "Two centuries apart, both revolutionaries of science are buried within a few steps of each other in Westminster Abbey in London, among England's greatest minds.|Separados por dos siglos, ambos revolucionarios de la ciencia están enterrados a pocos pasos el uno del otro en la abadía de Westminster, en Londres, junto a las mentes más grandes de Inglaterra.|Séparés par deux siècles, ces deux révolutionnaires de la science sont enterrés à quelques pas l'un de l'autre à l'abbaye de Westminster, à Londres, parmi les plus grands esprits d'Angleterre.|Separats per dos segles, tots dos revolucionaris de la ciència estan enterrats a pocs passos l'un de l'altre a l'abadia de Westminster, a Londres, al costat de les ments més grans d'Anglaterra."),
        Conn("curie", "franklin",
            "Both chemists made history studying radiation — Curie discovered polonium and radium, Franklin's X-ray images revealed the structure of DNA — and both likely died from illnesses linked to the very radiation that made their discoveries possible.|Ambas químicas hicieron historia estudiando la radiación —Curie descubrió el polonio y el radio, y las imágenes de rayos X de Franklin revelaron la estructura del ADN— y ambas murieron probablemente por enfermedades ligadas a la misma radiación que hizo posibles sus descubrimientos.|Ces deux chimistes sont entrées dans l'histoire en étudiant le rayonnement — Curie a découvert le polonium et le radium, les clichés aux rayons X de Franklin ont révélé la structure de l'ADN — et toutes deux sont probablement mortes de maladies liées au rayonnement même qui avait rendu leurs découvertes possibles.|Totes dues químiques van fer història estudiant la radiació: Curie va descobrir el poloni i el radi, i les imatges de raigs X de Franklin van revelar l'estructura de l'ADN; totes dues probablement van morir per malalties lligades a la mateixa radiació que va fer possibles els seus descobriments."),
        Conn("ibnbattuta", "champollion",
            "Centuries apart, both were captivated by Egypt: Ibn Battuta marveled at Cairo's wonders in his 14th-century travel writings, while Champollion spent his life unlocking the written words of the pharaohs who built them.|Separados por siglos, ambos quedaron cautivados por Egipto: Ibn Battuta se maravilló con las maravillas de El Cairo en sus escritos de viaje del siglo XIV, mientras que Champollion dedicó su vida a descifrar las palabras escritas de los faraones que las construyeron.|Séparés par des siècles, tous deux furent fascinés par l'Égypte : Ibn Battuta s'émerveillait des merveilles du Caire dans ses récits de voyage du XIVe siècle, tandis que Champollion consacra sa vie à déchiffrer les mots écrits des pharaons qui les avaient bâties.|Separats per segles, tots dos van quedar captivats per Egipte: Ibn Battuta es va meravellar amb les meravelles del Caire en els seus escrits de viatge del segle XIV, mentre que Champollion va dedicar la seva vida a desxifrar les paraules escrites dels faraons que les van construir."),
        Conn("newton", "smith",
            "Before writing about economics, Adam Smith wrote an essay praising Isaac Newton's method of discovering the hidden laws behind everyday events as the greatest triumph of human reasoning.|Antes de escribir sobre economía, Adam Smith escribió un ensayo elogiando el método de Isaac Newton para descubrir las leyes ocultas detrás de los hechos cotidianos, al que llamó el mayor triunfo del razonamiento humano.|Avant d'écrire sur l'économie, Adam Smith a rédigé un essai louant la méthode d'Isaac Newton pour découvrir les lois cachées derrière les événements du quotidien, qu'il qualifiait de plus grand triomphe du raisonnement humain.|Abans d'escriure sobre economia, Adam Smith va escriure un assaig elogiant el mètode d'Isaac Newton per descobrir les lleis ocultes darrere dels fets quotidians, al qual va anomenar el triomf més gran del raonament humà."),
        Conn("leonardo", "galileo",
            "A century before Galileo, Leonardo filled his notebooks with sketches and experiments on falling objects and friction that quietly anticipated Galileo's own discoveries about motion.|Un siglo antes que Galileo, Leonardo llenó sus cuadernos de bocetos y experimentos sobre la caída de los objetos y la fricción que, sin saberlo nadie entonces, se anticipaban a los propios descubrimientos de Galileo sobre el movimiento.|Un siècle avant Galilée, Léonard remplissait déjà ses carnets de croquis et d'expériences sur la chute des objets et le frottement, anticipant discrètement les propres découvertes de Galilée sur le mouvement.|Un segle abans que Galileu, Leonardo va omplir els seus quaderns d'esbossos i experiments sobre la caiguda dels objectes i la fricció que, sense que ningú ho sabés llavors, s'avançaven als propis descobriments de Galileu sobre el moviment."),
        Conn("curie", "noether",
            "Marie Curie and Emmy Noether worked in European universities around the same years, both fighting for recognition as women in fields — physics and mathematics — that rarely let women teach, let alone lead.|Marie Curie y Emmy Noether trabajaron en universidades europeas por los mismos años, ambas luchando por el reconocimiento como mujeres en campos —la física y las matemáticas— que apenas dejaban enseñar a las mujeres, y mucho menos dirigir.|Marie Curie et Emmy Noether ont travaillé dans des universités européennes à peu près aux mêmes années, luttant toutes deux pour être reconnues en tant que femmes dans des domaines — la physique et les mathématiques — qui laissaient rarement les femmes enseigner, et encore moins diriger.|Marie Curie i Emmy Noether van treballar en universitats europees pels mateixos anys, totes dues lluitant pel reconeixement com a dones en camps —la física i les matemàtiques— que amb prou feines deixaven ensenyar les dones, i encara menys dirigir."),
        Conn("cervantes", "leonardo",
            "Though a century and a different country apart, Cervantes and Leonardo both became the towering symbol of their homeland's golden age — one in painting and invention, the other in literature.|Aunque los separa un siglo y un país distinto, Cervantes y Leonardo se convirtieron cada uno en el símbolo mayor de la edad de oro de su tierra: uno en la pintura y la invención, el otro en la literatura.|Bien que séparés par un siècle et un pays différent, Cervantès et Léonard sont tous deux devenus le symbole majeur de l'âge d'or de leur patrie — l'un dans la peinture et l'invention, l'autre dans la littérature.|Tot i que els separa un segle i un país diferent, Cervantes i Leonardo es van convertir cadascun en el símbol major de l'edat d'or de la seva terra: l'un en la pintura i la invenció, l'altre en la literatura."),
        Conn("curie", "newton",
            "Marie Curie and Isaac Newton both rest among their nation's greatest figures — Newton in Westminster Abbey, Curie in the Panthéon in Paris, where she became the first woman honoured for her own achievements.|Marie Curie e Isaac Newton descansan ambos junto a las grandes figuras de su nación: Newton en la abadía de Westminster, y Curie en el Panteón de París, donde fue la primera mujer honrada por sus propios méritos.|Marie Curie et Isaac Newton reposent tous deux parmi les plus grandes figures de leur nation — Newton à l'abbaye de Westminster, Curie au Panthéon de Paris, où elle devint la première femme honorée pour ses propres mérites.|Marie Curie i Isaac Newton descansen tots dos al costat de les grans figures de la seva nació: Newton a l'abadia de Westminster, i Curie al Panteó de París, on va ser la primera dona honorada pels seus propis mèrits."),
        Conn("lovelace", "newton",
            "The mathematics Ada Lovelace was tutored in as a girl, including the mechanics of motion, was built on the foundations Isaac Newton had laid more than a century earlier.|Las matemáticas que le enseñaron a Ada Lovelace de niña, incluida la mecánica del movimiento, se construían sobre los cimientos que Isaac Newton había sentado más de un siglo antes.|Les mathématiques enseignées à Ada Lovelace durant son enfance, y compris la mécanique du mouvement, reposaient sur les fondations posées par Isaac Newton plus d'un siècle auparavant.|Les matemàtiques que li van ensenyar a Ada Lovelace de nena, incloent-hi la mecànica del moviment, es construïen sobre els fonaments que Isaac Newton havia establert més d'un segle abans."),
    ];

    /// <summary>All curated figure-to-figure connections, regardless of which figures the student has completed.
    /// Callers filter by completion to decide which ones to reveal.</summary>
    public static IReadOnlyList<FigureConnection> Connections() => ConnectionList;
